actions.script:
const out = ec.service.sync().name('org.moqui.impl.SipDeviceServices.create#SipDevice').parameters({name: name || null,
    deviceProfile: deviceProfile === 'legacy' ? 'legacy' : 'standard'}).requireNewTransaction(true).disableAuthz().call() || {}
if (!ec.message.hasError()) ec.message.addMessage(ec.resource.expand('Set up the phone with these; the password is shown only now. Username ${u}, password ${p}, domain ${d}, port ${port} (${tr}).', '',
    {u: out.username, p: out.password, d: out.domain, port: out.tlsPort || out.sipPort || '', tr: out.transport || ''}), 'success')

const out = ec.service.sync().name('org.moqui.impl.SipDeviceServices.rotate#SipDeviceCredential').parameter('sipDeviceId', sipDeviceId || '')
    .requireNewTransaction(true).disableAuthz().call() || {}
if (!ec.message.hasError()) ec.message.addMessage(ec.resource.expand('The old password no longer works. Username ${u}, new password ${p}; it is shown only now.', '',
    {u: out.username, p: out.password}), 'success')
